shell_rules.declarations:
width: min(100%,1520px);
  max-width: 1520px;
  min-height: 100vh;
  margin: 0 auto;
  padding-inline: 1px;
  overflow: hidden;
  background: transparent;
  border: 0;
  border-radius: 0;
  outline: 0;
  box-shadow: none;

footer_rules.declarations:
display: flex;
  justify-content: space-between;
  gap: 40px;
  align-items: center;
  margin: auto;
  color: var(--muted);
  font-size: 12px;

position: relative;
  isolation: isolate;
  max-width: var(--sg-max);
  padding: 35px 30px;
  overflow: visible;
  border-top: 1px solid transparent;
  background: transparent;

footer_surface_rules.declarations:
content: "";
  position: absolute;
  inset: -1px calc(50% - 50vw) 0;
  z-index: -1;
  pointer-events: none;
  border-top: 1px solid #29485d;
  background: #02070c;

header_transparency_source_review.declarations:
content: "";
  position: absolute;
  inset: 0 calc(50% - 50vw) -1px;
  z-index: -1;
  box-sizing: border-box;
  pointer-events: none;
  background: rgba(1,5,8,.75);
  border-bottom: 1px solid rgba(221,164,58,.30);
  box-shadow: 0 12px 34px rgba(0,0,0,.46),inset 0 -1px rgba(54,102,133,.22);
